///    executed command as proof the shell is alive.)
/// 2. Is alternate-screen content included in a read? Iteration 2 could not answer this: commands
///    were typed but never submitted, so the terminal never entered the alternate screen.
/// 3. Why does `GHOSTTY_POINT_SURFACE` return false where `GHOSTTY_POINT_SCREEN` works? That tag
///    backs the shipping `readFullSurface()` used by #49, so a genuine failure is a live bug.
///
/// Writes findings to `Application Support/Workroom/scrollback-spike/`.
enum ScrollbackSpike {
  static let marker = "SPIKE-REPLAY-MARKER-7F3A"
  static let readyMarker = "SPIKE-EXECUTED-OK-4C1D"
  static let altMarker = "SPIKE-ALTSCREEN-D904"
  static let scrollFirst = "SCROLLTEST-1-START"
  static let scrollLast = "SCROLLTEST-300-END"

  static var outputDirectory: URL {
    FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0]
      .appendingPathComponent("Workroom", isDirectory: true)
      .appendingPathComponent("scrollback-spike", isDirectory: true)
  }

  private static func write(_ name: String, _ contents: String) {
    let dir = outputDirectory
    try? FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
    try? contents.write(to: dir.appendingPathComponent(name), atomically: true, encoding: .utf8)
  }

  /// Every point tag, so "SURFACE is broken" can be separated from "SURFACE needs other arguments".
  private static func allTags(_ view: GhosttySurfaceView) -> String {
    let tags: [(String, ghostty_point_tag_e)] = [
      ("ACTIVE", GHOSTTY_POINT_ACTIVE),
      ("VIEWPORT", GHOSTTY_POINT_VIEWPORT),
      ("SCREEN", GHOSTTY_POINT_SCREEN),
      ("SURFACE", GHOSTTY_POINT_SURFACE),
    ]
    var out = ""
    for (name, tag) in tags {
      let flat = view.spikeRawRead(tag)
      out += "\(name): \(summary(flat))\n"
    }
    out += "SURFACE(rectangle=true): \(summary(view.spikeRawRead(GHOSTTY_POINT_SURFACE, rectangle: true)))\n"
    return out
  }

  private static func summary(_ raw: String) -> String {
    if raw.hasPrefix("OK(") {
      let head = raw.prefix(while: { $0 != "\n" })
      return "\(head) replay=\(raw.contains(marker)) executed=\(raw.contains(readyMarker)) "
        + "alt=\(raw.contains(altMarker)) scrollFirst=\(raw.contains(scrollFirst)) "
        + "scrollLast=\(raw.contains(scrollLast))"
    }
    return raw
  }

  static func run(on view: GhosttySurfaceView) {
    // CONTROL: every tag, before anything is written.
    schedule(3) {
      write("20-control.txt", allTags(view))
      view.spikeWriteBuffer("\(marker)\r\n── restored session ──\r\n")
    }

    // Q1: the injected bytes, plus a REAL executed command proving the shell survived.
    schedule(6) {
      write("21-after-write.txt", allTags(view))
      view.spikeSendLine("echo \(readyMarker)")
      view.spikePressReturn()
    }

    schedule(9) {
      write("22-after-executed-command.txt", allTags(view))
      // Scrollback depth: far more than a screenful.
      view.spikeSendLine("echo \(scrollFirst); for i in $(seq 2 299); do echo pad-$i; done; echo \(scrollLast)")
      view.spikePressReturn()
    }

    schedule(13) {
      write("23-scrollback-depth.txt", allTags(view))
      // Q2: enter the alternate screen for real.
      view.spikeSendLine("tput smcup; echo \(altMarker); sleep 10; tput rmcup")
      view.spikePressReturn()
    }

    schedule(18) {
      write("24-during-altscreen.txt", allTags(view))
    }

    schedule(32) {
      write("25-after-altscreen-exit.txt", allTags(view))
      write("99-done.txt", "spike complete\n")
    }
  }

  private static func schedule(_ seconds: TimeInterval, _ body: @escaping () -> Void) {
    DispatchQueue.main.asyncAfter(deadline: .now() + seconds) {
      MainActor.assumeIsolated(body)
    }
  }
