private func replayRestoredScrollback() {
  guard !didReplayScrollback, let surface, let restored = restoredScrollback,
    !restored.isEmpty
  else { return }
  didReplayScrollback = true
  var bytes = Array(Self.replayPayload(for: restored).utf8)
  ghostty_surface_write_buffer(surface, &bytes, UInt(bytes.count))
}

/// The exact bytes replayed into a restored pane: the captured text with **CRLF** line endings,
/// then the divider.
///
/// The CR is the whole point. `read_text` returns lines separated by bare `\n`, but a terminal
/// treats LF as "down one row, keep the column" — CR is what returns to column zero. Replaying the
/// captured text unchanged therefore staircases every line further right than the last, which is
/// exactly what it looked like. Normalise any existing CRLF down to LF first so this cannot double
/// the CR on text that already had it.
///
/// Pure and `nonisolated` so the rule is unit-testable without a surface.
nonisolated static func replayPayload(for text: String) -> String {
  let normalised = text.replacingOccurrences(of: "\r\n", with: "\n")
    .replacingOccurrences(of: "\n", with: "\r\n")
  return normalised + scrollbackDivider
}

// MARK: Replay payload

/// **REGRESSION.** `read_text` returns lines separated by bare `\n`, and a terminal treats LF as
/// "down one row, keep the column" — so replaying the capture unchanged staircased every line
/// further right than the last. CR is what returns to column zero.
func testReplayPayloadUsesCRLFLineEndings() {
  let payload = GhosttySurfaceView.replayPayload(for: "one\ntwo\nthree")
  XCTAssertTrue(payload.hasPrefix("one\r\ntwo\r\nthree"))
  XCTAssertFalse(
    payload.replacingOccurrences(of: "\r\n", with: "").contains("\n"),
    "no bare LF may survive — each one is a staircase step")
}

/// Text that already had CRLF must not end up with doubled carriage returns.
func testReplayPayloadDoesNotDoubleExistingCarriageReturns() {
  let payload = GhosttySurfaceView.replayPayload(for: "one\r\ntwo")
  XCTAssertTrue(payload.hasPrefix("one\r\ntwo"))
