import XCTest

@testable import Workroom

/// Finding a resumable agent conversation for a restored pane (issue #145).
///
/// Every test seeds a throwaway `$HOME`. Nothing here reads the developer's real `~/.claude` or
/// `~/.codex` — which is also what `AgentSessionIndex.forCurrentEnvironment` enforces at runtime, so
/// a unit test cannot pass or fail based on which directories someone talked to an agent in today.
final class AgentSessionIndexTests: XCTestCase {
  private var home: URL!
  private let savedAt = Date(timeIntervalSince1970: 1_800_000_000)

  override func setUpWithError() throws {
    try super.setUpWithError()
    home = FileManager.default.temporaryDirectory
      .appendingPathComponent("agent-index-\(UUID().uuidString)", isDirectory: true)
  }

  override func tearDownWithError() throws {
    try? FileManager.default.removeItem(at: home)
    try super.tearDownWithError()
  }

  private func makeIndex(limits: AgentSessionIndex.Limits = .standard, now: @escaping () -> Date = { Date() })
    -> AgentSessionIndex
  {
    AgentSessionIndex(roots: AgentSessionIndex.Roots(home: home), limits: limits, now: now)
  }

  private func write(_ lines: [String], to url: URL, modified: Date) throws {
    try FileManager.default.createDirectory(
      at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
    try (lines.joined(separator: "\n") + "\n").write(to: url, atomically: true, encoding: .utf8)
    try FileManager.default.setAttributes([.modificationDate: modified], ofItemAtPath: url.path)
  }

  /// A Claude transcript: line 1 is the `{leafUuid, sessionId, type}` summary that carries NO cwd,
  /// exactly as the real store writes it.
  @discardableResult
  private func seedClaude(
    directory: String, cwd: String, modified: Date? = nil, file: String = "session.jsonl"
  ) throws -> URL {
    let url = home.appendingPathComponent(".claude/projects/\(directory)/\(file)")
    try write(
      [
        #"{"leafUuid":"abc","sessionId":"s1","type":"summary"}"#,
        #"{"type":"user","cwd":"\#(cwd)","message":{"role":"user"}}"#,
      ], to: url, modified: modified ?? savedAt)
    return url
  }

  @discardableResult
  private func seedCodex(day: String, cwd: String, modified: Date? = nil, file: String = "rollout-a.jsonl")
    throws -> URL
  {
    let url = home.appendingPathComponent(".codex/sessions/\(day)/\(file)")
    try write(
      [#"{"type":"session_meta","timestamp":"t","payload":{"cwd":"\#(cwd)","id":"x"}}"#],
      to: url, modified: modified ?? savedAt)
    return url
  }

  /// `savedAt`'s own day, in the local calendar — the tree Codex writes into.
  private var savedAtDay: String {
    let formatter = DateFormatter()
    formatter.dateFormat = "yyyy/MM/dd"
    return formatter.string(from: savedAt)
  }

  // MARK: Claude

  func testFindsAClaudeConversationForTheExactDirectory() throws {
    let cwd = "/tmp/project"
    try seedClaude(directory: AgentSessionIndex.claudeSlugHint(for: cwd), cwd: cwd)

    let found = makeIndex().backends(forCwds: [cwd], savedAt: savedAt)
    XCTAssertEqual(found[cwd], [.claude])
  }

  /// **REGRESSION.** The slug is a hint, and the hint is allowed to be wrong.
  ///
  /// Claude's scheme is Claude's: it replaces `.` as well as `/`, and other character classes are
  /// undocumented. Keying identity on a reconstructed slug meant any directory we transformed
  /// differently silently showed no button, indistinguishable from "no history here". This seeds a
  /// directory the hint does NOT produce and asserts the conversation is found anyway — by the `cwd`
  /// the file itself records.
  func testFindsAConversationEvenWhenTheSlugHintIsWrong() throws {
    let cwd = "/tmp/a_b/project"
    let stored = "-tmp-a-b-project"  // what a slug rule we don't implement would have produced
    XCTAssertNotEqual(
      AgentSessionIndex.claudeSlugHint(for: cwd), stored, "the hint must genuinely miss here")
    try seedClaude(directory: stored, cwd: cwd)

    XCTAssertEqual(makeIndex().backends(forCwds: [cwd], savedAt: savedAt)[cwd], [.claude])
  }

  /// The documented `/a-b/c` vs `/a/b/c` collision is RESOLVED by exact matching, not accepted:
  /// both slug to the same directory name, and only the one whose recorded cwd matches counts.
  func testSlugCollidingDirectoriesAreToldApartByTheRecordedCwd() throws {
    let mine = "/a-b/c"
    let theirs = "/a/b/c"
    XCTAssertEqual(
      AgentSessionIndex.claudeSlugHint(for: mine), AgentSessionIndex.claudeSlugHint(for: theirs),
      "the collision must be real, or this test proves nothing")
    try seedClaude(directory: AgentSessionIndex.claudeSlugHint(for: mine), cwd: theirs)

    let found = makeIndex().backends(forCwds: [mine], savedAt: savedAt)
    XCTAssertNil(found[mine], "a sibling directory's conversation is not this pane's")
  }

  /// The `cwd` is not on line 1 — that is a summary record — so extraction has to scan forward.
  func testClaudeCwdIsReadPastTheSummaryFirstLine() {
    let lines = [
      #"{"leafUuid":"abc","sessionId":"s1","type":"summary"}"#,
      #"{"type":"user","cwd":"/tmp/project"}"#,
    ]
    XCTAssertEqual(AgentSessionIndex.claudeCwd(inLines: lines), "/tmp/project")
    XCTAssertNil(AgentSessionIndex.claudeCwd(inLines: [lines[0]]), "the summary alone has no cwd")
  }

  func testMalformedClaudeLinesAreIgnored() {
    XCTAssertNil(AgentSessionIndex.claudeCwd(inLines: []))
    XCTAssertNil(AgentSessionIndex.claudeCwd(inLines: ["not json at all"]))
    XCTAssertNil(AgentSessionIndex.claudeCwd(inLines: [#"{"type":"user"}"#]))
    XCTAssertNil(AgentSessionIndex.claudeCwd(inLines: [#"{"cwd":""}"#]), "an empty cwd is not a cwd")
  }

  func testSlugHintReplacesDotsAsWellAsSlashes() {
    // Measured against the real store: `/Users/x/.buzz` is kept as `-Users-x--buzz`.
    XCTAssertEqual(AgentSessionIndex.claudeSlugHint(for: "/Users/x/.buzz"), "-Users-x--buzz")
    XCTAssertEqual(AgentSessionIndex.claudeSlugHint(for: "/tmp/project"), "-tmp-project")
  }

  // MARK: Codex

  func testFindsACodexConversationByRecordedCwd() throws {
    let cwd = "/tmp/project"
    try seedCodex(day: savedAtDay, cwd: cwd)

    XCTAssertEqual(makeIndex().backends(forCwds: [cwd], savedAt: savedAt)[cwd], [.codex])
  }

  func testCodexCwdRequiresASessionMetaFirstLine() {
    XCTAssertEqual(
      AgentSessionIndex.codexCwd(
        inFirstLine: #"{"type":"session_meta","payload":{"cwd":"/tmp/p"}}"#), "/tmp/p")
    // A record kind we don't understand is a format we shouldn't guess at.
    XCTAssertNil(
      AgentSessionIndex.codexCwd(inFirstLine: #"{"type":"response_item","payload":{"cwd":"/tmp/p"}}"#))
    XCTAssertNil(AgentSessionIndex.codexCwd(inFirstLine: ""))
    XCTAssertNil(AgentSessionIndex.codexCwd(inFirstLine: "plain text"))
    XCTAssertNil(AgentSessionIndex.codexCwd(inFirstLine: #"{"type":"session_meta"}"#))
  }

  func testBothAgentsQualifyingYieldsBothRatherThanAGuess() throws {
    let cwd = "/tmp/project"
    try seedClaude(directory: AgentSessionIndex.claudeSlugHint(for: cwd), cwd: cwd)
    try seedCodex(day: savedAtDay, cwd: cwd)

    XCTAssertEqual(makeIndex().backends(forCwds: [cwd], savedAt: savedAt)[cwd], [.claude, .codex])
  }

  // MARK: Recency

  func testRecencyWindowBoundaries() {
    let window = AgentSessionIndex.recencyWindow
    XCTAssertTrue(AgentSessionIndex.isRecent(savedAt, savedAt: savedAt))
    XCTAssertTrue(
      AgentSessionIndex.isRecent(savedAt.addingTimeInterval(-window), savedAt: savedAt),
      "the boundary itself qualifies")
    XCTAssertTrue(AgentSessionIndex.isRecent(savedAt.addingTimeInterval(window), savedAt: savedAt))
    XCTAssertFalse(
      AgentSessionIndex.isRecent(savedAt.addingTimeInterval(-window - 1), savedAt: savedAt))
  }

  /// A future mtime is clock skew or a restored backup, not evidence the session is irrelevant.
  func testAFutureDatedSessionStillQualifies() {
    XCTAssertTrue(
      AgentSessionIndex.isRecent(savedAt.addingTimeInterval(60 * 60), savedAt: savedAt))
  }

  /// **REGRESSION.** Twelve hours, not the five minutes first proposed: a transcript's mtime is its
  /// last message, so an agent left idle at its prompt before you quit is the COMMON case, and a
  /// five-minute window would have missed exactly the conversation the feature exists to reopen.
  func testAnAgentIdleForFortyMinutesBeforeTheQuitStillQualifies() throws {
    let cwd = "/tmp/project"
    try seedClaude(
      directory: AgentSessionIndex.claudeSlugHint(for: cwd), cwd: cwd,
      modified: savedAt.addingTimeInterval(-40 * 60))

    XCTAssertEqual(makeIndex().backends(forCwds: [cwd], savedAt: savedAt)[cwd], [.claude])
  }

  func testAStaleConversationIsNotOffered() throws {
    let cwd = "/tmp/project"
    try seedClaude(
      directory: AgentSessionIndex.claudeSlugHint(for: cwd), cwd: cwd,
      modified: savedAt.addingTimeInterval(-5 * 24 * 60 * 60))

    XCTAssertNil(makeIndex().backends(forCwds: [cwd], savedAt: savedAt)[cwd])
  }

  // MARK: Path comparison

  func testTrailingSlashesAndSymlinksMatchButCaseIsNotFolded() throws {
    XCTAssertTrue(AgentSessionIndex.pathsMatch("/tmp/project/", "/tmp/project"))
    XCTAssertTrue(AgentSessionIndex.pathsMatch("/tmp/project", "/tmp/project"))
    XCTAssertFalse(AgentSessionIndex.pathsMatch("", "/tmp/project"))

    // Case-folding would merge two genuinely different directories on a case-sensitive volume.
    XCTAssertFalse(AgentSessionIndex.pathsMatch("/tmp/Project", "/tmp/project"))

    let target = home.appendingPathComponent("real", isDirectory: true)
    let link = home.appendingPathComponent("link", isDirectory: true)
    try FileManager.default.createDirectory(at: target, withIntermediateDirectories: true)
    try FileManager.default.createSymbolicLink(at: link, withDestinationURL: target)
    XCTAssertTrue(
      AgentSessionIndex.pathsMatch(link.path, target.path),
      "a session recorded through a symlink is the same directory")
  }

  // MARK: Bounds

  /// **REGRESSION.** A Codex store accumulates one file per session forever, so "read them all" is
  /// not a bound. Discovery runs on the launch path; an unbounded scan there is the bug.
  func testTheFileCapStopsTheScan() throws {
    let cwd = "/tmp/project"
    for index in 0..<50 {
      try seedCodex(day: savedAtDay, cwd: "/tmp/other-\(index)", file: "rollout-\(index).jsonl")
    }
    // The one that WOULD match, seeded last so the cap is hit before reaching it.
    try seedCodex(day: savedAtDay, cwd: cwd, file: "rollout-zzz.jsonl")

    var limits = AgentSessionIndex.Limits.standard
    limits.maxFiles = 5
    XCTAssertNil(
      makeIndex(limits: limits).backends(forCwds: [cwd], savedAt: savedAt)[cwd],
      "a capped scan publishes what it found, not what it would have found")
  }

  func testTheDeadlineStopsTheScan() throws {
    let cwd = "/tmp/project"
    try seedCodex(day: savedAtDay, cwd: cwd)

    var limits = AgentSessionIndex.Limits.standard
    limits.deadline = 1
    // A clock that jumps a minute per reading — the first budget check is already past the deadline.
    var ticks = 0
    let index = makeIndex(limits: limits) {
      defer { ticks += 1 }
      return Date(timeIntervalSince1970: Double(ticks) * 60)
    }
    XCTAssertNil(index.backends(forCwds: [cwd], savedAt: savedAt)[cwd])
  }

  func testCancellationStopsTheScan() throws {
    let cwd = "/tmp/project"
    try seedClaude(directory: AgentSessionIndex.claudeSlugHint(for: cwd), cwd: cwd)

    let found = makeIndex().backends(forCwds: [cwd], savedAt: savedAt, isCancelled: { true })
    XCTAssertNil(found[cwd])
  }

  /// A symlinked candidate file is a path out of the store we were pointed at; following one would
  /// let anything that can write into an agent directory aim our reads elsewhere.
  func testSymlinkedCandidateFilesAreNotFollowed() throws {
    let cwd = "/tmp/project"
    let real = home.appendingPathComponent("elsewhere/session.jsonl")
    try write(
      [#"{"type":"user","cwd":"/tmp/project"}"#], to: real, modified: savedAt)

    let directory = home.appendingPathComponent(
      ".claude/projects/\(AgentSessionIndex.claudeSlugHint(for: cwd))", isDirectory: true)
    try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
    try FileManager.default.createSymbolicLink(
      at: directory.appendingPathComponent("session.jsonl"), withDestinationURL: real)

    XCTAssertNil(makeIndex().backends(forCwds: [cwd], savedAt: savedAt)[cwd])
  }

  // MARK: Absence

  func testAMissingStoreYieldsNoOffersAndNoThrow() {
    XCTAssertTrue(makeIndex().backends(forCwds: ["/tmp/project"], savedAt: savedAt).isEmpty)
  }

  func testNoCwdsIsANoOp() {
    XCTAssertTrue(makeIndex().backends(forCwds: [], savedAt: savedAt).isEmpty)
  }

  /// The store belongs to the developer, not to the test suite.
  func testDiscoveryIsDisabledUnderXCTestWithNoSeededRoot() {
    XCTAssertNil(
      AgentSessionIndex.forCurrentEnvironment(),
      "a unit test must never read the real ~/.claude")
  }
}

import XCTest

@testable import Workroom

/// Offer state for restored panes (issue #145).
///
/// The two properties worth pinning are both about damage: an offer must not fight with a diagnosis
/// over one tab, and it must not be spendable twice — the action starts a **billed** agent session.
@MainActor
final class AgentResumeCoordinatorTests: XCTestCase {
  private var home: URL!
  private let savedAt = Date(timeIntervalSince1970: 1_800_000_000)

  override func setUpWithError() throws {
    try super.setUpWithError()
    home = FileManager.default.temporaryDirectory
      .appendingPathComponent("agent-resume-\(UUID().uuidString)", isDirectory: true)
  }

  override func tearDownWithError() throws {
    try? FileManager.default.removeItem(at: home)
    try super.tearDownWithError()
  }

  private func makeCoordinator() -> AgentResumeCoordinator {
    AgentResumeCoordinator(index: AgentSessionIndex(roots: AgentSessionIndex.Roots(home: home)))
  }

  private func seedClaude(cwd: String) throws {
    let url = home.appendingPathComponent(
      ".claude/projects/\(AgentSessionIndex.claudeSlugHint(for: cwd))/session.jsonl")
    try FileManager.default.createDirectory(
      at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
    try (#"{"type":"user","cwd":"\#(cwd)"}"# + "\n").write(
      to: url, atomically: true, encoding: .utf8)
    try FileManager.default.setAttributes(
      [.modificationDate: savedAt], ofItemAtPath: url.path)
  }

  private func pane(_ cwd: String) -> TerminalSessions.RestoredTerminal {
    TerminalSessions.RestoredTerminal(tabID: UUID(), targetID: "wr|/p|foo", cwd: cwd)
  }

  /// Discovery hops to a background queue and back, so wait for the offer rather than assuming.
  private func waitForOffer(
    _ coordinator: AgentResumeCoordinator, tab: TerminalTab.ID, timeout: TimeInterval = 5
  ) -> Set<AgentBackend>? {
    let deadline = Date().addingTimeInterval(timeout)
    while Date() < deadline {
      if let offer = coordinator.offers[tab] { return offer }
      RunLoop.current.run(mode: .default, before: Date().addingTimeInterval(0.01))
    }
    return coordinator.offers[tab]
  }

  private func settle(_ seconds: TimeInterval = 0.5) {
    let deadline = Date().addingTimeInterval(seconds)
    while Date() < deadline {
      RunLoop.current.run(mode: .default, before: Date().addingTimeInterval(0.01))
    }
  }

  // MARK: Offers

  func testARestoredPaneWithHistoryGetsAnOffer() throws {
    let cwd = "/tmp/project"
    try seedClaude(cwd: cwd)
    let coordinator = makeCoordinator()
    let restored = pane(cwd)

    coordinator.discover([restored], savedAt: savedAt)
    XCTAssertEqual(waitForOffer(coordinator, tab: restored.tabID), [.claude])
  }

  func testAPaneWithNoHistoryGetsNothing() {
    let coordinator = makeCoordinator()
    let restored = pane("/tmp/empty")

    coordinator.discover([restored], savedAt: savedAt)
    settle()
    XCTAssertNil(coordinator.offers[restored.tabID])
  }

  func testDiscoveringNothingIsANoOp() {
    let coordinator = makeCoordinator()
    coordinator.discover([], savedAt: savedAt)
    settle(0.1)
    XCTAssertTrue(coordinator.offers.isEmpty)
  }

  /// The fixture default: no index means discovery does nothing at all, which is what keeps the
  /// existing UI tests off the developer's real `~/.claude`.
  func testANilIndexDisablesDiscoveryEntirely() throws {
    let cwd = "/tmp/project"
    try seedClaude(cwd: cwd)
    let coordinator = AgentResumeCoordinator(index: nil)
    let restored = pane(cwd)

    coordinator.discover([restored], savedAt: savedAt)
    settle()
    XCTAssertNil(coordinator.offers[restored.tabID])
  }

  // MARK: Spending the offer

  /// **CRITICAL REGRESSION.** `consume` removes the offer BEFORE returning the command.
  ///
  /// Without that, a double-click — or SwiftUI evaluating the button's action twice — starts two
  /// agent sessions, and agent sessions cost money. The second call returning nil is the button
  /// being spent, not a failure.
  func testConsumeIsAtomicSoADoubleClickCannotSpendTwice() throws {
    let cwd = "/tmp/project"
    try seedClaude(cwd: cwd)
    let coordinator = makeCoordinator()
    let restored = pane(cwd)
    coordinator.discover([restored], savedAt: savedAt)
    XCTAssertNotNil(waitForOffer(coordinator, tab: restored.tabID))

    let first = coordinator.consume(tab: restored.tabID, backend: .claude)
    let second = coordinator.consume(tab: restored.tabID, backend: .claude)

    XCTAssertEqual(first?.arguments, ["--resume"])
    XCTAssertNil(second, "the offer is spent")
    XCTAssertNil(coordinator.offers[restored.tabID], "and the button is gone")
  }

  func testConsumingAnAgentThatWasNotOfferedReturnsNothing() throws {
    let cwd = "/tmp/project"
    try seedClaude(cwd: cwd)
    let coordinator = makeCoordinator()
    let restored = pane(cwd)
    coordinator.discover([restored], savedAt: savedAt)
    XCTAssertEqual(waitForOffer(coordinator, tab: restored.tabID), [.claude])

    XCTAssertNil(coordinator.consume(tab: restored.tabID, backend: .codex))
    XCTAssertNotNil(coordinator.offers[restored.tabID], "and Claude's offer survives")
  }

  // MARK: Lifecycle

  /// **REGRESSION.** Discovery is async, so an offer can land after the user has started typing.
  /// Appending `claude --resume` plus Return to a half-typed line runs something nobody asked for.
  func testTypingInThePaneBeforeTheOfferLandsSuppressesIt() throws {
    let cwd = "/tmp/project"
    try seedClaude(cwd: cwd)
    let coordinator = makeCoordinator()
    let restored = pane(cwd)

    coordinator.discover([restored], savedAt: savedAt)
    coordinator.paneReceivedInput(tab: restored.tabID)
    settle()

    XCTAssertNil(coordinator.offers[restored.tabID], "a dirty input line must not be typed into")
  }

  func testTypingAfterTheOfferLandsRemovesIt() throws {
    let cwd = "/tmp/project"
    try seedClaude(cwd: cwd)
    let coordinator = makeCoordinator()
    let restored = pane(cwd)
    coordinator.discover([restored], savedAt: savedAt)
    XCTAssertNotNil(waitForOffer(coordinator, tab: restored.tabID))

    coordinator.paneReceivedInput(tab: restored.tabID)
    XCTAssertNil(coordinator.offers[restored.tabID])
    XCTAssertNil(coordinator.consume(tab: restored.tabID, backend: .claude))
  }

  func testAClosedPaneDropsItsOfferAndCannotBeResurrectedByALateScan() throws {
    let cwd = "/tmp/project"
    try seedClaude(cwd: cwd)
    let coordinator = makeCoordinator()
    let restored = pane(cwd)

    coordinator.discover([restored], savedAt: savedAt)
    coordinator.tabClosed(restored.tabID)
    settle()

    XCTAssertNil(coordinator.offers[restored.tabID])
  }

  func testCancellingDiscoveryPublishesNothing() throws {
    let cwd = "/tmp/project"
    try seedClaude(cwd: cwd)
    let coordinator = makeCoordinator()
    let restored = pane(cwd)

    coordinator.discover([restored], savedAt: savedAt)
    coordinator.cancelDiscovery()
    settle()

    XCTAssertNil(coordinator.offers[restored.tabID])
  }

  // MARK: Independence from the diagnosis banner

  /// **CRITICAL REGRESSION.** An offer and a diagnosis are separate state, in both orders.
  ///
  /// The tempting design was a sixth `AgentBannerState` case. `TerminalAgentManager.banners` is one
  /// slot per tab, so that would mean: a restored pane offers Resume, the user runs a command, it
  /// fails, `commandFinished` overwrites the offer and it never comes back. And symmetrically — a
  /// scan finishing late would stomp a diagnosis the user is waiting on.
  func testAnOfferAndADiagnosisCoexistOnOneTabInEitherOrder() throws {
    let cwd = "/tmp/project"
    try seedClaude(cwd: cwd)
    let coordinator = makeCoordinator()
    let manager = TerminalAgentManager(runner: StubAgentRunner(envelope: ""), featureEnabled: { true })
    let restored = pane(cwd)
    let failure = FailedCommand(
      command: "npm test", cwd: cwd, exitCode: 1, shell: "zsh", output: "boom", isRunTab: false,
      isRemote: false)

    // Offer first, then a failing command.
    coordinator.discover([restored], savedAt: savedAt)
    XCTAssertNotNil(waitForOffer(coordinator, tab: restored.tabID))
    manager.commandFinished(tab: restored.tabID, target: restored.targetID, failure: failure)

    XCTAssertNotNil(manager.banners[restored.tabID], "the diagnosis is there")
    XCTAssertNotNil(coordinator.offers[restored.tabID], "and it did not evict the offer")

    // And the other way round: a second pane that fails first, then gets its offer.
    let other = pane(cwd)
    manager.commandFinished(tab: other.tabID, target: other.targetID, failure: failure)
    coordinator.discover([other], savedAt: savedAt)
    XCTAssertNotNil(waitForOffer(coordinator, tab: other.tabID))

    XCTAssertNotNil(manager.banners[other.tabID], "the late offer did not stomp the diagnosis")
    XCTAssertNotNil(coordinator.offers[other.tabID])
  }
}

import XCTest

@testable import Workroom

/// The command a Resume click runs (issue #145).
///
/// Small tests guarding an expensive mistake: these two argv forms are the difference between "pick
/// a conversation" and "silently reopen whichever one was last, in both panes".
final class AgentResumeInvocationTests: XCTestCase {

  func testClaudeResumesThroughThePicker() {
    let invocation = AgentInvocationBuilder.resume(.claude)
    XCTAssertEqual(invocation.executable, "claude")
    XCTAssertEqual(invocation.arguments, ["--resume"])
    XCTAssertEqual(invocation.commandLine, "claude --resume")
  }

  func testCodexResumesThroughThePicker() {
    let invocation = AgentInvocationBuilder.resume(.codex)
    XCTAssertEqual(invocation.executable, "codex")
    XCTAssertEqual(invocation.arguments, ["resume"])
    XCTAssertEqual(invocation.commandLine, "codex resume")
  }

  /// **The whole point of the feature.** `claude --continue` and `codex resume --last` both reopen
  /// the newest conversation *for the current directory*, and two agent panes in one workroom share
  /// a directory — so both panes would land in the same conversation, confidently and wrongly. The
  /// app cannot know which pane owned which session, so it asks.
  func testNeitherAgentEverSkipsThePicker() {
    for backend in AgentBackend.allCases {
      let invocation = AgentInvocationBuilder.resume(backend)
      XCTAssertFalse(invocation.arguments.contains("--continue"), "\(backend) must not auto-continue")
      XCTAssertFalse(invocation.arguments.contains("-c"), "\(backend) must not auto-continue")
      XCTAssertFalse(invocation.arguments.contains("--last"), "\(backend) must not auto-resume")
      XCTAssertFalse(invocation.commandLine.contains("--continue"))
      XCTAssertFalse(invocation.commandLine.contains("--last"))
    }
  }

  /// Nothing read off disk reaches the command line, but the join is the place a future caller could
  /// change that, so it is pinned.
  func testCommandLineQuotesOnlyWhatNeedsIt() {
    XCTAssertEqual(
      AgentInvocation(executable: "claude", arguments: ["--model", "sonnet"]).commandLine,
      "claude --model sonnet")
    XCTAssertEqual(
      AgentInvocation(executable: "claude", arguments: ["hello world"]).commandLine,
      "claude 'hello world'")
    XCTAssertEqual(
      AgentInvocation(executable: "claude", arguments: ["it's"]).commandLine,
      #"claude 'it'\''s'"#)
    XCTAssertEqual(
      AgentInvocation(executable: "claude", arguments: ["; rm -rf /"]).commandLine,
      "claude '; rm -rf /'")
    XCTAssertEqual(
      AgentInvocation(executable: "claude", arguments: [""]).commandLine, "claude ''")
  }

  func testDisplayNamesAreSeparateFromExecutables() {
    XCTAssertEqual(AgentBackend.claude.displayName, "Claude")
    XCTAssertEqual(AgentBackend.claude.executable, "claude")
    XCTAssertEqual(AgentBackend.codex.displayName, "Codex")
    XCTAssertEqual(AgentBackend.codex.executable, "codex")
  }
}

